/* @autogenerated */
package net.civeira.phylax.feature.observe.health;

import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

import io.micrometer.core.instrument.Gauge;
import io.micrometer.core.instrument.MeterRegistry;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Instance;
import net.civeira.phylax.feature.observe.config.ObservabilitySettings;
import net.civeira.phylax.feature.observe.ingest.ObservePipeline;
import net.civeira.phylax.feature.observe.source.SourceRegistry;
import net.civeira.phylax.feature.observe.store.TelemetryStore;

/**
 * Health of the collector itself: queue, writer, disk and the activity of each source. If the
 * collector stops or loses data, the viewer would show "no errors"; this is what says it is not so.
 * It feeds the health check of the application, the Micrometer gauges and the viewer.
 */
@ApplicationScoped
public class ObserveHealth {

  /**
   * DOWN: the writer is stuck with the queue full. DEGRADED: it drops events, the disk is nearly
   * full or the store is at its limit and rejects events.
   */
  public enum Status {
    UP, DEGRADED, DOWN
  }

  private static final long STUCK_MILLIS = 60_000;

  private final ObservePipeline pipeline;
  private final TelemetryStore store;
  private final ObservabilitySettings settings;
  private final SourceRegistry registry;
  private final Instance<MeterRegistry> meters;
  private final AtomicBoolean gauges = new AtomicBoolean();
  private volatile long previousDropped = -1;
  private volatile long droppedLastMinute;
  private volatile Instant lastPurge;

  public ObserveHealth(final ObservePipeline pipeline, final TelemetryStore store,
      final ObservabilitySettings settings, final SourceRegistry registry,
      final Instance<MeterRegistry> meters) {
    this.pipeline = pipeline;
    this.store = store;
    this.settings = settings;
    this.registry = registry;
    this.meters = meters;
  }

  /** Registers the gauges (observe.queue.size, observe.dropped, observe.disk.bytes...). */
  public void start() {
    if (!meters.isResolvable() || !gauges.compareAndSet(false, true)) {
      return;
    }
    MeterRegistry meter = meters.get();
    Gauge.builder("observe.queue.size", pipeline, p -> p.stats().queueSize()).register(meter);
    Gauge.builder("observe.accepted", pipeline, p -> p.stats().accepted()).register(meter);
    Gauge.builder("observe.dropped", pipeline, p -> p.stats().dropped()).register(meter);
    Gauge.builder("observe.write.errors", pipeline, p -> p.stats().writeErrors()).register(meter);
    Gauge.builder("observe.disk.bytes", store, TelemetryStore::sizeBytes).register(meter);
    Gauge.builder("observe.rejected", store, TelemetryStore::rejected).register(meter);
  }

  /** Every minute: the events dropped since the previous call. */
  public void tick() {
    long dropped = pipeline.dropped();
    droppedLastMinute = previousDropped < 0 ? 0 : dropped - previousDropped;
    previousDropped = dropped;
  }

  public void purged(final Instant when) {
    lastPurge = when;
  }

  public Status status() {
    ObservePipeline.Stats stats = pipeline.stats();
    long now = System.currentTimeMillis();
    boolean full = stats.queueSize() >= stats.capacity();
    boolean stuck = stats.running() && full
        && (0 == stats.lastBatchAt() || now - stats.lastBatchAt() > STUCK_MILLIS);
    if (!stats.running() || stuck) {
      return Status.DOWN;
    }
    if (droppedLastMinute > 0 || store.full() || diskRatio() > 0.9) {
      return Status.DEGRADED;
    }
    return Status.UP;
  }

  /** Used fraction of max-disk-mb (0 without limit). */
  public double diskRatio() {
    long max = settings.current().maxDiskMb() * 1024 * 1024;
    return max <= 0 ? 0 : (double) store.sizeBytes() / max;
  }

  /** The collector block (queue, writer, disk); the viewer shows it to the ADMIN level. */
  public Map<String, Object> collector() {
    ObservePipeline.Stats stats = pipeline.stats();
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("status", status().name());
    result.put("running", stats.running());
    result.put("queueSize", stats.queueSize());
    result.put("capacity", stats.capacity());
    result.put("accepted", stats.accepted());
    result.put("dropped", stats.dropped());
    result.put("droppedLastMinute", droppedLastMinute);
    result.put("writeErrors", stats.writeErrors());
    result.put("lastBatchSize", stats.lastBatchSize());
    result.put("lastBatchMillis", stats.lastBatchMillis());
    result.put("lastBatchAt", 0 == stats.lastBatchAt() ? null : stats.lastBatchAt());
    result.put("diskBytes", store.sizeBytes());
    result.put("maxDiskMb", settings.current().maxDiskMb());
    result.put("diskRatio", Math.round(diskRatio() * 1000) / 1000.0);
    result.put("storeFull", stats.storeFull());
    result.put("rejected", stats.rejected());
    result.put("lastPurge", null == lastPurge ? null : lastPurge.toEpochMilli());
    return result;
  }

  /** Activity of each source: last contact, minutes of silence, events per minute, drops. */
  public List<Map<String, Object>> sources() {
    long now = System.currentTimeMillis();
    List<Map<String, Object>> result = new ArrayList<>();
    for (SourceRegistry.Source source : registry.all()) {
      Map<String, Object> row = new LinkedHashMap<>();
      Long seen = registry.lastSeen(source.code()).orElse(null);
      row.put("code", source.code());
      row.put("accepting", source.accepting());
      row.put("lastSeen", seen);
      row.put("silentMinutes", null == seen ? null : (now - seen) / 60_000);
      row.put("expectedEveryMinutes",
          source.expectedEveryMinutes() > 0 ? source.expectedEveryMinutes() : null);
      row.put("eventsPerMinute", Math.round(registry.eventsPerMinute(source.code()) * 10) / 10.0);
      row.put("dropped", registry.dropped(source.code()));
      row.put("release", registry.lastRelease(source.code()).orElse(null));
      result.add(row);
    }
    result.sort((a, b) -> String.valueOf(a.get("code")).compareTo(String.valueOf(b.get("code"))));
    return result;
  }
}
